WITH if(has([${service_name:sqlstring}], '.*'), '.*', arrayStringConcat(arrayMap(v -> regexpQuoteMeta(v), [${service_name:sqlstring}]), '|')) AS demo_var_service_name
SELECT timestamp AS time, if(isFinite(value), value, NULL) AS "memory_usage_pct",
  mapFromArrays(arrayMap(t -> t.1, tags), arrayMap(t -> t.2, tags)) AS labels
FROM prometheusQuery(demo_metrics, concat('sum by (service_instance_id_host_name) (
  label_join(
    (
      (
        sum by (service_instance_id, host_name) (
          system_memory_usage_bytes{job="", state!="free"}
        )
        /
        sum by (service_instance_id, host_name) (
          system_memory_usage_bytes{job=""}
        )
      )
      * on(host_name) group_right (
        max by (host_name, service_instance_id) (target_info{service_name=~', toJSONString(demo_var_service_name), '})
      )
    ),
    "service_instance_id_host_name",
    " / ",
    "service_instance_id",
    "host_name"
  )
)'), toDateTime64('{end}', 3, 'UTC'))
